#!/usr/bin/env bash
# Full re-measurement driver (runs on VM1 under nohup). Idempotent: completed runs (DONE) are skipped,
# so it can simply be started again after an interruption.
# Usage: orchestrate.sh [plan_file]   default plan: $W/plan.txt (generated by make_plan.sh)
source "$(dirname "$0")/env.sh"
PLAN=${1:-$W/plan.txt}
mkdir -p "$RES" "$STATE" "$RES/warmup"
log "orchestrator start pid=$$ plan=$PLAN lines=$(grep -vc '^#' $PLAN)"
ensure_net() {
  local want=$1
  [ "$(cat $STATE/current_net 2>/dev/null)" = "$want" ] && return 0
  bash "$SCRIPTS/net_switch.sh" "$want" && return 0
  log "net_switch $want failed (rc=$?), retrying in 60 s"; sleep 60
  bash "$SCRIPTS/net_switch.sh" "$want"
}
disk_ok() {
  local f0 f1
  f0=$(pi $PI0 "df -k / | awk 'NR==2{print \$4}'"); f1=$(pi $PI1 "df -k / | awk 'NR==2{print \$4}'")
  echo "$(date -u +%FT%TZ) pi0_free_kb=$f0 pi1_free_kb=$f1" >> "$STATE/disk.log"
  [ "${f0:-0}" -gt 700000 ] && [ "${f1:-0}" -gt 700000 ]
}
warmup() { # scen tagfile
  local sc=$1 name=$2 f="$RES/warmup/$2.csv"
  [ -e "$f" ] && f="$RES/warmup/$2.$(date -u +%H%M%S).csv"
  bash "$SCRIPTS/client.sh" "$(scen_net $sc)" "$(scen_mode $sc)" 1 20 "$f" "${sc}wup"
  echo "warmup $name ok=$(awk -F, 'NR>1&&$7==0' $f | wc -l)/20"
}
pprof_run() { # scen run ntx
  local sc=$1 run=$2 ntx=$3 D=$RES/pprof/$1/$2
  [ -f "$D/DONE" ] && return 0
  [ -e "$D" ] && mv "$D" "$D.incomplete.$(date -u +%Y%m%dT%H%M%SZ)"
  mkdir -p "$D"; net_env "$(scen_net $sc)"
  { echo "scenario=$sc"; echo "net=$NET"; echo "pprof_port=$PPROF"; echo "leader=$LEADER"; echo "load_tx=$ntx"; } > "$D/run_meta.txt"
  bash "$SCRIPTS/client.sh" "$NET" "$(scen_mode $sc)" 1 "$ntx" "$D/load_invoke_latency.csv" "${sc}prf" & local cp=$!
  sleep 20
  for k in 1 2 3; do
    pi $PI0 "bash $PI_REMOTE_DIR/pi_snap.sh $P0C $MPORT" > "$D/snap_w${k}_pre.txt"
    echo "window${k}_start_ms=$(now_ms)" >> "$D/run_meta.txt"
    pi $PI0 "curl -s -o $PI_REMOTE_DIR/prof_${sc}_${run}_$k.pb 'http://localhost:$PPROF/debug/pprof/profile?seconds=60'"
    echo "window${k}_end_ms=$(now_ms)" >> "$D/run_meta.txt"
    pi $PI0 "bash $PI_REMOTE_DIR/pi_snap.sh $P0C $MPORT" > "$D/snap_w${k}_post.txt"
    pi_get $PI0 "$PI_REMOTE_DIR/prof_${sc}_${run}_$k.pb" "$D/profile_$k.pb"
  done
  wait $cp
  echo "load_ok=$(awk -F, 'NR>1&&$7==0' $D/load_invoke_latency.csv | wc -l)" >> "$D/run_meta.txt"
  ls -l "$D"/profile_*.pb > "$D/DONE"
}
grep -v '^#' "$PLAN" | while read -r PH SC CONC RUN NTX COL; do
  [ -z "$PH" ] && continue
  if [ "$PH" = pprof ]; then [ -f "$RES/pprof/$SC/$RUN/DONE" ] && continue
  else [ -f "$RES/$PH/$SC/c$CONC/$RUN/DONE" ] && continue; fi
  date -u +%FT%TZ > "$STATE/heartbeat"
  ensure_net "$(scen_net $SC)" < /dev/null || { log "ABORT: cannot switch to $(scen_net $SC)"; exit 1; }
  disk_ok < /dev/null || { log "ABORT: Pi unreachable or disk below 700 MB ($(tail -1 $STATE/disk.log))"; exit 1; }
  log "begin $PH $SC c=$CONC $RUN ntx=$NTX collect=$COL leader=$(cat $STATE/leader_$(scen_net $SC))"
  log "$(warmup $SC ${PH}_${SC}_c${CONC}_${RUN} < /dev/null)"
  if [ "$PH" = pprof ]; then pprof_run "$SC" "$RUN" "$NTX" < /dev/null; log "end pprof $SC $RUN $(wc -l < $RES/pprof/$SC/$RUN/DONE 2>/dev/null) profiles"
  else log "$(bash $SCRIPTS/run_one.sh $PH $SC $CONC $RUN $NTX $COL < /dev/null 2>&1 | tail -1)"; fi
  sleep 5
done
log "orchestrator finished"
